#include "DelayCore.h"
#include <iostream>
#include <cstdlib>
using namespace fsd;
void check(bool b,const char* msg){if(!b){std::cerr<<"FAIL: "<<msg<<'\n';std::exit(1);}}
int main(){Core c;c.prepare(48000);Settings s;s.sync=false;s.left=s.right=100;s.link=true;s.mix=100;s.feedback=0;s.depth=0;s.saturation=0;s.mode=0;s.safety=false;float peak=0;int at=-1;for(int n=0;n<10000;n++){auto o=c.tick(n==0?.5f:0,0,s,120);if(std::abs(o[0])>peak){peak=std::abs(o[0]);at=n;}}check(at==4800&&std::abs(peak-.5f)<.001,"100ms delay impulse");c.reset();s.bypass=true;auto y=c.tick(.23f,-.4f,s,120);check(y[0]==.23f&&y[1]==-.4f,"bypass transparent");s.bypass=false;s.safety=true;s.safe=-1;s.feedback=119;s.left=30;s.right=60;s.link=false;s.mix=70;s.depth=10;for(int m=0;m<12;m++){s.mode=m;c.reset();float energy=0;for(int n=0;n<48000;n++){auto o=c.tick(n<2000?.8f*std::sin(n*.1f):0,n<2000?.6f*std::sin(n*.13f):0,s,120);for(float x:o){check(std::isfinite(x),"finite output");check(std::abs(x)<=db(-1)+.00001f,"safe ceiling");if(n>3000)energy+=std::abs(x);}}check(energy>.001,"audible mode tail");std::cout<<"Mode "<<m<<" finite, bounded, audible tail\n";}c.reset();s.mode=0;s.feedback=40;s.depth=0;s.saturation=0;s.left=20;s.link=true;s.mix=100;s.safe=-1;for(int n=0;n<2000;n++)c.tick(n==0?.5f:0,0,s,120);s.freeze=true;float e=0;for(int n=0;n<10000;n++){auto o=c.tick(0,0,s,120);e+=std::abs(o[0]);}check(e>.001,"freeze retains tail");c.reset();for(int n=0;n<4000;n++){auto o=c.tick(0,0,s,120);check(o[0]==0&&o[1]==0,"clear silence");}std::cout<<"PASS: timing, bypass, 12 engines, safety, hold, clear\n";}
